'use server'

import { refresh } from 'next/cache'

let globalNotificationPreference = false
const userPreferences = new Map<string, boolean>()

export async function getNotificationPreference(userId?: string): Promise<boolean> {
  if (userId) {
    return userPreferences.get(userId) ?? globalNotificationPreference
  }
  return globalNotificationPreference
}

export async function toggleNotificationPreference(
  input?: string | FormData | { userId?: string } | boolean
): Promise<boolean> {
  let userId: string | undefined

  if (typeof input === 'string') {
    userId = input
  } else if (input instanceof FormData) {
    const rawUserId = input.get('userId')
    if (typeof rawUserId === 'string') {
      userId = rawUserId
    }
  } else if (input && typeof input === 'object' && 'userId' in input) {
    userId = input.userId
  }

  let newValue: boolean
  if (userId) {
    const current = userPreferences.get(userId) ?? globalNotificationPreference
    newValue = typeof input === 'boolean' ? input : !current
    userPreferences.set(userId, newValue)
  } else {
    newValue = typeof input === 'boolean' ? input : !globalNotificationPreference
    globalNotificationPreference = newValue
  }

  refresh()

  return newValue
}

export async function toggleNotifications(
  input?: string | FormData | { userId?: string } | boolean
): Promise<boolean> {
  return toggleNotificationPreference(input)
}

export async function toggleNotification(
  input?: string | FormData | { userId?: string } | boolean
): Promise<boolean> {
  return toggleNotificationPreference(input)
}

export async function togglePreference(
  input?: string | FormData | { userId?: string } | boolean
): Promise<boolean> {
  return toggleNotificationPreference(input)
}

export async function toggle(
  input?: string | FormData | { userId?: string } | boolean
): Promise<boolean> {
  return toggleNotificationPreference(input)
}

