import { describe, it, expect, vi, beforeEach } from 'vitest'

const mockRefresh = vi.fn()
vi.mock('next/cache', () => ({
  refresh: () => mockRefresh(),
}))

describe('Notification actions', () => {
  beforeEach(() => {
    mockRefresh.mockClear()
  })

  it('toggles notification preference and calls refresh', async () => {
    const { toggleNotificationPreference, getNotificationPreference, setNotificationPreference } = await import('./app/actions')
    await setNotificationPreference(false)
    expect(await getNotificationPreference()).toBe(false)

    const result1 = await toggleNotificationPreference()
    expect(result1).toBe(true)
    expect(await getNotificationPreference()).toBe(true)
    expect(mockRefresh).toHaveBeenCalledTimes(1)

    const result2 = await toggleNotificationPreference()
    expect(result2).toBe(false)
    expect(await getNotificationPreference()).toBe(false)
    expect(mockRefresh).toHaveBeenCalledTimes(2)
  })

  it('works with FormData as well', async () => {
    const { toggleNotificationPreference, getNotificationPreference, setNotificationPreference } = await import('./app/actions')
    await setNotificationPreference(false)
    const formData = new FormData()
    await toggleNotificationPreference(formData)
    expect(await getNotificationPreference()).toBe(true)
    expect(mockRefresh).toHaveBeenCalled()
  })
})
